CREATE TABLE IF NOT EXISTS settings (`key` VARCHAR(80) PRIMARY KEY,value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS staff(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(80) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('admin','reception','therapist','finance') NOT NULL DEFAULT 'reception', active TINYINT NOT NULL DEFAULT 1, color VARCHAR(8) NOT NULL DEFAULT '#0b8b7f',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS patients(pid BIGINT AUTO_INCREMENT PRIMARY KEY,fname VARCHAR(80) NOT NULL,lname VARCHAR(100) NOT NULL,phone_cell VARCHAR(20) NULL UNIQUE,national_id VARCHAR(20) NULL UNIQUE,DOB DATE NULL,sex VARCHAR(20) NOT NULL DEFAULT '',email VARCHAR(160) NOT NULL DEFAULT '',address TEXT NOT NULL,emergency_name VARCHAR(160) NOT NULL DEFAULT '',emergency_phone VARCHAR(20) NOT NULL DEFAULT '',notes TEXT NOT NULL,allow_patient_portal VARCHAR(3) NOT NULL DEFAULT 'NO',providerID BIGINT NOT NULL DEFAULT 0,active TINYINT NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(lname,fname)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS resources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,kind ENUM('room','equipment') NOT NULL,active TINYINT NOT NULL DEFAULT 1,UNIQUE(name,kind)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS services(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160) NOT NULL,price BIGINT UNSIGNED NOT NULL DEFAULT 0,duration INT UNSIGNED NOT NULL DEFAULT 30,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS login_limits(bucket CHAR(64) PRIMARY KEY,window_start BIGINT NOT NULL,attempts INT NOT NULL DEFAULT 0) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit(id BIGINT AUTO_INCREMENT PRIMARY KEY,actor BIGINT NOT NULL,action VARCHAR(80) NOT NULL,entity BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
